          class="tab-item"
          :class="{ active: activeStatus === tab.value }"
          @click="activeStatus = tab.value"
        >
          <text class="tab-text">{{ tab.name }}</text>
        </view>
      </view>

      <!-- 批量下载按钮 (如果需要) -->
      <view v-if="selectedOrders.length > 0" class="batch-actions">
        <button class="batch-btn" @click="downloadSelectedOrders">
          批量下载 ({{ selectedOrders.length }})
        </button>
      </view>

      <!-- 订单列表 -->
      <scroll-view class="order-list" scroll-y>
        <view v-if="filteredOrders.length > 0" class="order-container">
          <view
            v-for="order in filteredOrders"
            :key="order.id"
            class="order-card"
            @click="handleOrderClick(order)"
          >
            <!-- 主内容容器（避开勾选框位置） -->
            <view class="card-content">
              <!-- 订单头部：订单号 + 状态 -->
              <view class="order-header">
                <text class="order-number">订单号: ****{{ order.orderId.slice(-4) }}</text>
                <view class="status-badge" :class="getStatusClass(order.status)">
                  <text class="status-text">{{ getStatusText(order.status) }}</text>
                </view>
              </view>

              <!-- 服务类型 -->
              <text class="service-type">{{ order.serviceType }} - {{ order.hospitalName }}</text>

              <!-- 服务时间 & 价格 -->
              <view class="order-meta">
                <text class="service-time">服务时间: {{ order.serviceDate }} {{ order.startTime }}</text>
                <text class="price" :class="{ pending: order.status === 'pending' }">
                  {{ order.status === 'pending' ? '待支付' : order.price }}
                </text>
              </view>

              <!-- 分割线 -->
              <view class="divider"></view>

              <!-- 陪诊师信息 & 操作按钮 (移除下载按钮，添加删除按钮) -->
              <view class="doctor-info">
                <!-- 修改：使用根据姓名获取头像的方法 -->
                <image class="doctor-avatar" :src="getAvatarByAttendantName(order.attendantName)" mode="aspectFill"></image>
                <view class="doctor-detail">
                  <!-- 修改：显示陪诊师名称 -->
                  <text class="doctor-name">{{ order.attendantName }}</text>
                  <text class="rating">
                    <text class="star" v-for="i in 5" :key="i">
                      {{ i <= order.rating ? '★' : '☆' }}
                    </text>
                  </text>
                </view>
                <view class="action-buttons">
                  <button class="btn detail-btn" @click.stop="handleDetailClick(order)">查看详情</button>
                  <!-- 新增：删除订单按钮，仅在已完成或已取消状态下显示 -->
                  <button
                    v-if="order.status === 'completed' || order.status === 'cancelled'"
                    class="btn delete-btn"
                    @click.stop="handleDeleteClick(order)"
                  >
                    删除订单
                  </button>
                </view>
              </view>
            </view>

            <!-- 勾选框（绝对定位到左侧） -->
            <view class="checkbox-wrapper">
              <checkbox
                :value="order.id"
                :checked="selectedOrders.includes(order.id)"
                @change="handleCheckboxChange($event, order.id)"
                style="transform: scale(0.8);"
              />
            </view>
          </view>
        </view>

        <!-- 空状态 -->
        <view v-else class="empty-state">
          <image class="empty-icon" src="/static/order.png" mode="aspectFit"></image>
          <text class="empty-text">暂无符合条件的订单</text>
          <text class="empty-subtext">请检查筛选条件或稍后再试</text>
        </view>
      </scroll-view>
    </view>
  </view>
</template>

<script setup>
import { ref, computed, onMounted } from 'vue';
import { onShow } from '@dcloudio/uni-app';

// 系统信息
const statusBarHeight = ref(0);

// 搜索
const searchKeyword = ref('');

// 状态标签 (修改：新增进行中、已完成)
const statusTabs = ref([
  { name: '全部', value: 'all' },
  { name: '待接单', value: 'assigned' },
  { name: '进行中', value: 'in_progress' }, // 新增
  { name: '已完成', value: 'completed' }, // 修改：值为 'completed'
  { name: '待支付', value: 'pending' },
  { name: '已取消', value: 'cancelled' }
]);
const activeStatus = ref('all');

// 选中订单
const selectedOrders = ref([]);

// ========================
// 🔧 从本地存储读取订单数据
// ========================
const ORDERS_STORAGE_KEY = 'all_orders'; // 本地存储键名

// 初始化订单数据
const orders = ref([]);

// 生成演示订单数据 (整合 ServiceCompanionSelect.vue 示例数据)
function generateDemoOrders() {
  const demoOrders = [
    {
      id: '1001',
      orderId: 'ORD202512270001',
      status: 'pending', // 待支付
      serviceType: '普通陪诊',
      serviceTime: '2025-12-28 10:00',
      serviceDate: '2025-12-28',
      startTime: '10:00',
      hospitalName: '中山大学附属第一医院',
      contactPerson: '张三',
      price: '¥150.00',
      paymentMethod: '微信支付',
      payTime: '2025-12-27 09:30',
      attendantName: '王丽', // 示例陪诊师名
      attendantPhone: '13800138000',
      // attendantAvatar: '/static/provider1.jpg', // 注释掉，使用新方法
      rating: 4.8,
    },
    {
      id: '1002',
      orderId: 'ORD202512270002',
      status: 'assigned', // 待陪诊师接单
      serviceType: '专家陪诊',
      serviceTime: '2025-12-28 14:00',
      serviceDate: '2025-12-28',
      startTime: '14:00',
      hospitalName: '南方医科大学珠江医院',
      contactPerson: '李四',
      price: '¥280.00',
      paymentMethod: '支付宝',
      payTime: '2025-12-27 11:15',
      attendantName: '张伟', // 示例陪诊师名
      attendantPhone: '13800138001',
      // attendantAvatar: '/static/38da0ad384c9103b9b6de1a987e16191.jpg', // 注释掉，使用新方法
      rating: 4.9,
    },
    {
      id: '1003',
      orderId: 'ORD202512270003',
      status: 'in_progress', // 进行中
      serviceType: '普通陪诊',
      serviceTime: '2025-12-27 15:00',
      serviceDate: '2025-12-27',
      startTime: '15:00',
      hospitalName: '广州医科大学附属第三医院',
      contactPerson: '王五',
      price: '¥150.00',
      paymentMethod: '微信支付',
      payTime: '2025-12-27 08:00',
      attendantName: '刘芳', // 示例陪诊师名
      attendantPhone: '13800138002',
      // attendantAvatar: '/static/1a13f15c8114696a50ebd020c621cc8f.jpg', // 注释掉，使用新方法
      rating: 4.7,
    },
    {
      id: '1004',
      orderId: 'ORD202512270004',
      status: 'completed', // 已完成
      serviceType: '陪诊+报告解读',
      serviceTime: '2025-12-26 09:30',
      serviceDate: '2025-12-26',
      startTime: '09:30',
      hospitalName: '广东省人民医院',
      contactPerson: '孙六',
      price: '¥320.00',
      paymentMethod: '银联卡',
      payTime: '2025-12-26 08:45',
      attendantName: '王丽', // 示例陪诊师名
      attendantPhone: '13800138000',
      // attendantAvatar: '/static/provider1.jpg', // 注释掉，使用新方法
      rating: 4.95,
    },
    {
      id: '1005',
      orderId: 'ORD202512270005',
      status: 'cancelled', // 已取消
      serviceType: '普通陪诊',
      serviceTime: '2025-12-29 11:00',
      serviceDate: '2025-12-29',
      startTime: '11:00',
      hospitalName: '中山大学附属第三医院',
      contactPerson: '周七',
      price: '¥150.00',
      paymentMethod: '微信支付',
      payTime: '2025-12-27 07:00',
      attendantName: '张伟', // 示例陪诊师名
      attendantPhone: '13800138001',
      // attendantAvatar: '/static/38da0ad384c9103b9b6de1a987e16191.jpg', // 注释掉，使用新方法
      rating: 4.6,
    },
  ];
  // ⚠️ 注意：这里不再写入任何缓存！这是纯净的数据生成函数。
  return demoOrders;
}

// 模拟异步加载数据
onMounted(async () => {
  const systemInfo = uni.getSystemInfoSync();
  statusBarHeight.value = systemInfo.statusBarHeight || 0;

  // 从本地存储加载订单
  loadOrdersFromStorage();
});

// --- 你可能需要在页面显示时也更新订单数据 ---
onShow(() => {
  loadOrdersFromStorage(); // 每次页面显示时刷新订单数据
});

// 从本地存储加载订单数据
function loadOrdersFromStorage() {
  try {
    const storedOrders = uni.getStorageSync(ORDERS_STORAGE_KEY);
    if (storedOrders && Array.isArray(storedOrders) && storedOrders.length > 0) {
      // 如果缓存中已有数据，直接使用
      orders.value = storedOrders;
      console.log('【order.vue】从缓存加载的订单列表:', orders.value);
    } else {
      // 如果缓存中没有数据，生成演示数据并存入缓存
      const demoOrders = generateDemoOrders();
      orders.value = demoOrders;
      // 💡 关键：只在第一次初始化时将数据存入缓存
      uni.setStorageSync(ORDERS_STORAGE_KEY, orders.value);
      // 💡 关键：为每个演示订单创建单独的缓存项，确保详情页能读取到
      demoOrders.forEach(order => {
        const orderKey = `order_${order.id}`;
        uni.setStorageSync(orderKey, order);
        console.log(`【order.vue】为订单 ${order.id} 创建缓存项: ${orderKey}`);
      });
      console.log('【order.vue】演示数据已加载并缓存到 all_orders 和各自的 order_XXX 项中');
    }
  } catch (e) {
    console.error('读取本地存储订单数据失败:', e);
    // 如果读取失败，使用演示数据，但不尝试写入缓存，避免再次失败
    orders.value = generateDemoOrders();
  }
}

// ======== 新增：根据陪诊师姓名获取头像路径的方法 ========
const getAvatarByAttendantName = (name) => {
  // 定义一个陪诊师姓名到头像路径的映射表
  const avatarMap = {
    '王丽': '/static/provider1.jpg',
    '张伟': '/static/38da0ad384c9103b9b6de1a987e16191.jpg',
    '刘芳': '/static/1a13f15c8114696a50ebd020c621cc8f.jpg',
    // 你可以根据需要添加更多陪诊师及其对应的头像路径
    // '李四': '/static/lisi.jpg',
    // '赵六': '/static/zhaoliu.jpg',
  };

  // 如果姓名在映射表中，则返回对应的头像路径
  if (name && avatarMap[name]) {
    return avatarMap[name];
  }

  // 如果姓名不在映射表中或为空，则返回默认头像
  return '/static/default-avatar.jpg';
};
// ======== 结束新增 ========

// 过滤订单
const filteredOrders = computed(() => {
  let result = [...orders.value];

  // 1. 按状态筛选
  if (activeStatus.value !== 'all') {
    result = result.filter((order) => order.status === activeStatus.value);
  }

  // 2. 按关键词搜索 (如果需要)
  if (searchKeyword.value.trim()) {
    const keyword = searchKeyword.value.toLowerCase();
    result = result.filter(
      (order) =>
        order.orderId.toLowerCase().includes(keyword) ||
        order.hospitalName.toLowerCase().includes(keyword) ||
        order.serviceType.toLowerCase().includes(keyword)
    );
  }

  return result;
});

// 获取状态样式类
const getStatusClass = (status) => {
  switch (status) {
    case 'assigned':
      return 'status-assigned';
    case 'in_progress':
      return 'status-in-progress';
    case 'completed':
      return 'status-completed';
    case 'pending':
      return 'status-pending';
    case 'cancelled':
      return 'status-cancelled';
    default:
      return 'status-default';
  }
};

// 获取状态文本
const getStatusText = (status) => {
  switch (status) {
    case 'assigned':
      return '待陪诊师接单';
    case 'in_progress':
      return '进行中';
    case 'completed':
      return '已完成';
    case 'pending':
      return '待支付';
    case 'cancelled':
      return '已取消';
    default:
      return '未知状态';
  }
};

// 处理 checkbox 勾选变化
const handleCheckboxChange = (e, orderId) => {
  const checked = e.detail.value.length > 0;
  if (checked) {
    if (!selectedOrders.value.includes(orderId)) {
      selectedOrders.value.push(orderId);
    }
  } else {
    selectedOrders.value = selectedOrders.value.filter((id) => id !== orderId);
  }
};

// 下载选中订单
const downloadSelectedOrders = () => {
  if (selectedOrders.value.length === 0) return;
  uni.showToast({
    title: `已选择 ${selectedOrders.value.length} 个订单，即将批量下载`,
  });
  // 这里可以实现下载逻辑
};

// 处理订单点击 (跳转详情)
const handleOrderClick = (order) => {
  if (!order?.id) {
    uni.showToast({ title: '无效订单', icon: 'none' });
    return;
  }
  // 传递订单的 id 作为参数
  uni.navigateTo({
    url: `/pages/OrderDetailPage/OrderDetailPage?orderNo=${order.id}`,
  }).catch((err) => {
    console.error('跳转失败:', err);
    uni.showToast({ title: '页面不存在', icon: 'none' });
  });
};

// 查看详情 (跳转详情)
const handleDetailClick = (order) => {
  handleOrderClick(order);
};

// 处理删除订单点击
const handleDeleteClick = (order) => {
  uni.showModal({
    title: '确认删除',
    content: `确定要删除订单 ${order.orderId} 吗？此操作不可撤销。`,
    success: (res) => {
      if (res.confirm) {
        const updatedOrders = orders.value.filter((o) => o.id !== order.id);
        orders.value = updatedOrders;
        uni.setStorageSync(ORDERS_STORAGE_KEY, updatedOrders);
        // 删除对应的单个订单缓存
        uni.removeStorageSync(`order_${order.id}`);
        console.log(`【order.vue】删除订单 ${order.id} 的缓存项`);
        uni.showToast({ title: '删除成功', icon: 'success' });
      }
    },
    fail: (err) => {
      console.error('弹窗确认失败:', err);
    },
  });
};

// 搜索处理
const handleSearch = () => {
  console.log('搜索:', searchKeyword.value);
};
</script>

